DROP TASK IF EXISTS GEN_AI_POC_SNOWFLAKECOE.SDLC_WIZARD.TASK_SP_LOAD_AEROSPACE_PARTS_SCD1;

-- ============================================================
-- SECTION 4: CREATE SNOWFLAKE TASK
-- Define the Snowflake Task TASK_SP_LOAD_AEROSPACE_PARTS_SCD1
