-- ============================================================

-- Create the Snowflake Task to schedule the aerospace parts pipeline
CREATE OR REPLACE TASK GEN_AI_POC_SNOWFLAKECOE.SDLC_WIZARD.TASK_SP_LOAD_AEROSPACE_PARTS_SCD1
    WAREHOUSE = COMPUTE_WH
