-- ============================================================
-- SECTION 7: TASK HISTORY QUERY
-- Query the task run history to monitor execution status,
-- duration, and errors after the task has been running.
-- Useful for SLA monitoring (BRD: 5-minute SLA for 1M records)
-- and for confirming successful daily executions.
-- ============================================================

-- Query task execution history for the last 7 days
SELECT
    NAME,
    DATABASE_NAME,
    SCHEMA_NAME,
    QUERY_ID,
    STATE,
    ERROR_CODE,
    ERROR_MESSAGE,
    SCHEDULED_TIME,
    QUERY_START_TIME,
    COMPLETED_TIME,
    DATEDIFF('second', QUERY_START_TIME, COMPLETED_TIME) AS DURATION_SECONDS,
    RETURN_VALUE
FROM
    TABLE(
        GEN_AI_POC_SNOWFLAKECOE.INFORMATION_SCHEMA.TASK_HISTORY(
            SCHEDULED_TIME_RANGE_START => DATEADD('day', -7, CURRENT_TIMESTAMP()),
            TASK_NAME                  => 'TASK_SP_LOAD_AEROSPACE_PARTS_SCD1'
        )
    )
